from pathlib import Path
p=Path(__file__).resolve().parent
raw=(p/'genfft-data/3.program').read_bytes();(p/'genfft-data/collision.program').write_bytes(raw[1:2]+raw[:1]+raw[2:])
lines=['structure NeedGenerator=BenchHartelGenFftFn(BenchNeed)','structure StrictGenerator=BenchHartelGenFftFn(BenchStrict)','structure NeedDriver=BenchHartelGenFftDriverFn(NeedGenerator)','structure StrictDriver=BenchHartelGenFftDriverFn(StrictGenerator)','structure GenFftTests =','struct','  structure N=NeedGenerator','  structure R=StrictGenerator','  fun read name=let val f=TextIO.openIn name val s=TextIO.inputAll f val _=TextIO.closeIn f in s end','  fun code s=CharVector.foldl(fn(c,sum)=>sum+Char.ord c)0 s+String.size s','  fun chars xs=case BenchNeed.force xs of N.Nil=>[]|N.Cons(x,rest)=>BenchNeed.force x::chars rest','  fun strictChars xs=case BenchStrict.force xs of R.Nil=>[]|R.Cons(x,rest)=>BenchStrict.force x::strictChars rest']
for n in range(9):
 raw=(p/'genfft-data'/(str(n)+'.program')).read_bytes();expected=(sum(raw)+len(raw),len(raw))
 for mode,k in [('lazy','N'),('strict','R')]:lines.append(f'  val _=T.check("genfft/{mode}-complete-{n}",fn()=>{k}.check {n}(read "{n}.program")=({expected[0]},{expected[1]}))')
for n in [3,6,8]:
 raw=(p/'genfft-data'/(str(n)+'.program')).read_bytes();checksum=str(sum(raw)+len(raw))+'/'+str(len(raw));expected='2:'+checksum+':'+str(2*(len(checksum)+1))
 for mode,k in [('lazy','NeedDriver'),('strict','StrictDriver')]:lines.append(f'  val _=T.check("genfft/{mode}-repeat-{n}",fn()=>{k}.run["{n}","2","{n}.program"]="{expected}")')
for name in ['wrong','truncated','extra','collision']:
 for mode,k in [('lazy','N'),('strict','R')]:lines.append(f'  val _=T.check("genfft/{mode}-reject-{name}",fn()=>((ignore({k}.check 3(read "{name}.program"));false)handle Fail message=>String.isPrefix "incorrect result:" message))')
lines+=['  val _=T.check("genfft/collision-has-same-source-checksum",fn()=>','    let val a=read "3.program" val b=read "collision.program"','    in a<>b andalso String.size a=String.size b andalso code a=code b end)','  val _=T.check("genfft/take-zero-does-not-demand-source",fn()=>','    case BenchNeed.force(N.take 0(BenchNeed.delay(fn()=>raise Fail "unused source")))of N.Nil=>true|_=>false)','  val _=T.check("genfft/append-shares-character-cell",fn()=>','    let val count=ref 0 val cell=BenchNeed.delay(fn()=>(count:= !count+1;#"x"))','        val source=BenchNeed.delay(fn()=>N.Cons(cell,N.empty()))','    in String.implode(chars(N.append source source))="xx"andalso !count=1 end)','  val _=T.check("genfft/singleton-glue-does-not-demand-separator",fn()=>','    String.implode(chars(N.glue(BenchNeed.delay(fn()=>raise Fail "unused separator"))(N.texts[N.text "ab"])))="ab")','  val _=T.check("genfft/lazy-empty-glue-is-partial",fn()=>((ignore(BenchNeed.force(N.glue(N.text "-")(N.empty())));false)handle Empty=>true))','  val _=T.check("genfft/strict-empty-glue-is-partial",fn()=>((ignore(R.glue(R.text "-")(R.empty()));false)handle Empty=>true))','  val _=T.check("genfft/strict-singleton-glue",fn()=>String.implode(strictChars(R.glue(R.text "-")(R.texts[R.text "ab"])))="ab")','end']
(p/'genfft-tests.sml').write_text('\n'.join(lines)+'\n');(p/'genfft-test-data.txt').write_text(''.join(f.name+'\n'for f in sorted((p/'genfft-data').iterdir())if f.suffix=='.program'))
root=Path.cwd();files=['tests/basis/harness.sml','examples/benchmarks/shared/input.sml','examples/benchmarks/shared/lazy.sml','examples/benchmarks/shared/suspend.sml',str(p/'genfft.sml'),str(p/'genfft-driver.sml'),str(p/'genfft-tests.sml'),'tests/basis/finish.sml'];(p/'genfft-test-sources.txt').write_text(''.join(str(root/f)+'\n'for f in files))
